(27561, 'Matthew 10:40', 'Matthew', 10, 40, 'څوک چې تاسو قبول کړي، نو زه یې قبول کړی یم او څوک چې ما قبول کړي، نو هغه څوک یې قبول کړی دی چې زه یې رالېږلی یم.', 'چوک چې تاسو قبول کری، نو زه یې قبول کری یم او چوک چې ما قبول کری، نو هغه چوک یې قبول کری دی چې زه یې رالېزلی یم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_10_40.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27562, 'Matthew 10:41', 'Matthew', 10, 41, 'هرڅوک چې یو پیغمبر په دې خاطر قبول کړي چې هغه پیغمبر دی، نو هغه به د یو پیغمبر اجر ومومي او څوک چې یو نېک سړی په دې خاطر قبول کړي چې هغه نېک سړی دی، نو هغه به د نېک سړي اجر ومومي.', 'هرچوک چې یو پیغمبر په دې خاطر قبول کری چې هغه پیغمبر دی، نو هغه به د یو پیغمبر اجر ومومی او چوک چې یو نېک سری په دې خاطر قبول کری چې هغه نېک سری دی، نو هغه به د نېک سری اجر ومومی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_10_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27563, 'Matthew 10:42', 'Matthew', 10, 42, 'هرڅوک چې د دې عادي خلکو څخه یوه ته په دې خاطر چې هغه زما د پیروانو څخه دی، یوه پیاله یخې اوبه هم ورکړي، نو په یقین سره زه تاسو ته دا وایم چې هغه سړی به بې‌اجره پاتې نه شي.»', 'هرچوک چې د دې عادی خلکو چخه یوه ته په دې خاطر چې هغه زما د پیروانو چخه دی، یوه پیاله یخې اوبه هم ورکری، نو په یقین سره زه تاسو ته دا وایم چې هغه سری به بې‌اجره پاتې نه شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_10_42.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27564, 'Luke 6:1', 'Luke', 6, 1, 'د سبت په یوه ورځ عیسی د خپلو شاګردانو سره د غنمو په پټیو تېرېده. شاګردانو یې د غنمو وږي راشکول او په لاسونو کې یې موږل او خوړل یې.', 'د سبت په یوه ورج عیسی د خپلو شاګردانو سره د غنمو په پتیو تېرېده. شاګردانو یې د غنمو وزی راشکول او په لاسونو کې یې موزل او خورل یې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27565, 'Luke 6:2', 'Luke', 6, 2, 'ځینو فریسیانو پوښتنه وکړه: «تاسو ولې داسې کار کوئ چې د سبت په ورځ ناروا دی؟»', 'جینو فریسیانو پوشتنه وکره: «تاسو ولې داسې کار کوی چې د سبت په ورج ناروا دی؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27566, 'Luke 6:3', 'Luke', 6, 3, 'عیسی هغوی ته په ځواب کې وویل: «ایا تاسو دا نه دي لوستلي کله چې داود او ملګري یې وږي شوي وو، نو هغه څه وکړل؟', 'عیسی هغوی ته په جواب کې وویل: «ایا تاسو دا نه دی لوستلی کله چې داود او ملګری یې وزی شوی وو، نو هغه چه وکرل؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27567, 'Luke 6:4', 'Luke', 6, 4, 'هغه د خدای کور ته ننوت، سپېڅلې ډوډۍ یې راواخیستله او ویې خوړه او خپلو ملګرو ته یې هم ورکړه، که څه هم د هغې ډوډۍ خوړل له کاهنانو پرته بل چاته روا نه وو.»', 'هغه د خدای کور ته ننوت، سپېچلې دودی یې راواخیستله او ویې خوره او خپلو ملګرو ته یې هم ورکره، که چه هم د هغې دودی خورل له کاهنانو پرته بل چاته روا نه وو.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27568, 'Luke 6:5', 'Luke', 6, 5, 'بیا عیسی وویل: «د انسان زوی د سبت د ورځې خاوند هم دی.» عیسی د سبت په ورځ ناروغانو ته شفا ورکوي (متي ۱۲‏:‌۹‌‏-‌۱۴ او مرقوس ۳‏:‌۱‌‏-‌۶)', 'بیا عیسی وویل: «د انسان زوی د سبت د ورجې خاوند هم دی.» عیسی د سبت په ورج ناروغانو ته شفا ورکوی (متی ۱۲‏:‌۹‌‏-‌۱۴ او مرقوس ۳‏:‌۱‌‏-‌۶)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27569, 'Luke 6:6', 'Luke', 6, 6, 'د بل سبت په ورځ عیسی کنیسې ته ننوت او تعلیم یې ورکاوه. هلته یو سړی ؤ چې ښي لاس یې وچ شوی ؤ.', 'د بل سبت په ورج عیسی کنیسې ته ننوت او تعلیم یې ورکاوه. هلته یو سری و چې شی لاس یې وچ شوی و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27570, 'Luke 6:7', 'Luke', 6, 7, 'د شریعت ځینو عالمانو او فریسیانو په ځیر سره هغه ته کتل چې وویني ایا عیسی به د سبت په ورځ چاته شفا ورکوي که نه، ترڅو په هغه باندې د تور لګولو دپاره یو دلیل پیدا کړي.', 'د شریعت جینو عالمانو او فریسیانو په جیر سره هغه ته کتل چې ووینی ایا عیسی به د سبت په ورج چاته شفا ورکوی که نه، ترچو په هغه باندې د تور لګولو دپاره یو دلیل پیدا کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27571, 'Luke 6:8', 'Luke', 6, 8, 'عیسی د هغوی په فکرونو پوه شو او هغه سړي ته چې لاس یې وچ شوی ؤ وویل: «راپاڅېږه او د ټولو په مخکې ودرېږه.» نو هغه راپاڅېد او هلته ودرېده.', 'عیسی د هغوی په فکرونو پوه شو او هغه سری ته چې لاس یې وچ شوی و وویل: «راپاچېزه او د تولو په مخکې ودرېزه.» نو هغه راپاچېد او هلته ودرېده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27572, 'Luke 6:9', 'Luke', 6, 9, 'بیا عیسی هغوی ته وویل: «زه ستاسو څخه پوښتنه کوم: ایا د سبت په ورځ نېکي کول روا دي که بدي کول؟ د یو چا ژوند ژغورل، که له منځه وړل؟»', 'بیا عیسی هغوی ته وویل: «زه ستاسو چخه پوشتنه کوم: ایا د سبت په ورج نېکی کول روا دی که بدی کول؟ د یو چا ژوند ژغورل، که له منجه ورل؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27573, 'Luke 6:10', 'Luke', 6, 10, 'عیسی ګردچاپېره هغوی ټولو ته وکتل او بیا یې هغه سړي ته وویل: «خپل لاس دې وغزوه.» هغه خپل لاس وغزاوه او لاس یې روغ شو.', 'عیسی ګردچاپېره هغوی تولو ته وکتل او بیا یې هغه سری ته وویل: «خپل لاس دې وغزوه.» هغه خپل لاس وغزاوه او لاس یې روغ شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27574, 'Luke 6:11', 'Luke', 6, 11, 'خو د شریعت عالمان او فریسیان ډېر په قهر شول او یو بل ته یې وویل چې د عیسی سره څه وکړو. عیسی د خپلو شاګردانو څخه دولس رسولان ټاکي (متي ۱۰‏:‌۱‌‏-‌۴ او مرقوس ۳‏:‌۱۳‌‏-‌۱۹)', 'خو د شریعت عالمان او فریسیان دېر په قهر شول او یو بل ته یې وویل چې د عیسی سره چه وکرو. عیسی د خپلو شاګردانو چخه دولس رسولان تاکی (متی ۱۰‏:‌۱‌‏-‌۴ او مرقوس ۳‏:‌۱۳‌‏-‌۱۹)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27575, 'Luke 6:12', 'Luke', 6, 12, 'په هغو ورځو کې عیسی د دعا دپاره غره ته لاړ او ټوله شپه یې خدای ته په دعا کولو تېره کړه.', 'په هغو ورجو کې عیسی د دعا دپاره غره ته لار او توله شپه یې خدای ته په دعا کولو تېره کره.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27576, 'Luke 6:13', 'Luke', 6, 13, 'کله چې سهار شو، نو خپل شاګردان یې راوغوښتل او د هغوی له منځ نه یې دولس تنه غوره کړل او هغوی یې د رسولانو په نوم یاد کړل:', 'کله چې سهار شو، نو خپل شاګردان یې راوغوشتل او د هغوی له منج نه یې دولس تنه غوره کرل او هغوی یې د رسولانو په نوم یاد کرل:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27577, 'Luke 6:14', 'Luke', 6, 14, 'شمعون چې عیسی ورباندې پطروس نوم کېښود او د هغه ورور اندریاس، یعقوب، یوحنا، فیلیپوس او بارتولما،', 'شمعون چې عیسی ورباندې پطروس نوم کېشود او د هغه ورور اندریاس، یعقوب، یوحنا، فیلیپوس او بارتولما،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27578, 'Luke 6:15', 'Luke', 6, 15, 'متي، توما، یعقوب د حلفي زوی او شمعون چې په سرتېري مشهور ؤ', 'متی، توما، یعقوب د حلفی زوی او شمعون چې په سرتېری مشهور و', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27579, 'Luke 6:16', 'Luke', 6, 16, 'او یهودا د یعقوب زوی او یهودا اسخریوتي چې وروسته خاین شو. عیسی خلکو ته تعلیم او شفا ورکوي (متي ۴‏:‌۲۳‌‏-‌۲۵)', 'او یهودا د یعقوب زوی او یهودا اسخریوتی چې وروسته خاین شو. عیسی خلکو ته تعلیم او شفا ورکوی (متی ۴‏:‌۲۳‌‏-‌۲۵)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27580, 'Luke 6:17', 'Luke', 6, 17, 'عیسی د خپلو رسولانو سره د غره څخه راښکته شو او په یو هوار ځای کې ودرېده. په هغه ځای کې د هغه د پیروانو یوه لویه ډله او د ټولې یهودیې، اورشلیم او د صور او صیدون د ساحلي ښارونو څخه ګڼ شمېر خلک موجود وو.', 'عیسی د خپلو رسولانو سره د غره چخه راشکته شو او په یو هوار جای کې ودرېده. په هغه جای کې د هغه د پیروانو یوه لویه دله او د تولې یهودیې، اورشلیم او د صور او صیدون د ساحلی شارونو چخه ګن شمېر خلک موجود وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27581, 'Luke 6:18', 'Luke', 6, 18, 'دا خلک د دې دپاره راغلي وو چې د هغه خبرې واوري او د خپلو ناروغیو څخه روغ شي. همدارنګه هغه خلک چې پېریانو نیولي وو هم راغلي وو او روغ شول.', 'دا خلک د دې دپاره راغلی وو چې د هغه خبرې واوری او د خپلو ناروغیو چخه روغ شی. همدارنګه هغه خلک چې پېریانو نیولی وو هم راغلی وو او روغ شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27582, 'Luke 6:19', 'Luke', 6, 19, 'ټولو خلکو کوښښ کاوه چې عیسی ته لاس وروړي، ځکه چې د هغه څخه به یو قدرت راوته او ټول به یې روغول. خوشحالي او غم (متي ۵‏:‌۱‌‏-‌۱۲)', 'تولو خلکو کوشش کاوه چې عیسی ته لاس وروری، جکه چې د هغه چخه به یو قدرت راوته او تول به یې روغول. خوشحالی او غم (متی ۵‏:‌۱‌‏-‌۱۲)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27583, 'Luke 6:20', 'Luke', 6, 20, 'بیا عیسی خپلو شاګردانو ته مخ راواړاوه او ویې ویل: «بختور یئ تاسو چې اوس غریبان یئ، ځکه چې د خدای پاچاهي ستاسو ده.', 'بیا عیسی خپلو شاګردانو ته مخ راواراوه او ویې ویل: «بختور یی تاسو چې اوس غریبان یی، جکه چې د خدای پاچاهی ستاسو ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27584, 'Luke 6:21', 'Luke', 6, 21, 'بختور یئ تاسو چې اوس وږي یئ، ځکه چې تاسو به ماړه شئ. بختور یئ چې اوس ژاړئ، ځکه چې تاسو به وخاندئ.', 'بختور یی تاسو چې اوس وزی یی، جکه چې تاسو به ماره شی. بختور یی چې اوس ژاری، جکه چې تاسو به وخاندی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27585, 'Luke 6:22', 'Luke', 6, 22, 'بختور یئ تاسو چې خلک درڅخه د انسان د زوی په خاطر کرکه کوي او خپل منځ کې مو نه پرېږدي، سپکاوی درته کوي او تاسو بدناموي.', 'بختور یی تاسو چې خلک درچخه د انسان د زوی په خاطر کرکه کوی او خپل منج کې مو نه پرېزدی، سپکاوی درته کوی او تاسو بدناموی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27586, 'Luke 6:23', 'Luke', 6, 23, 'نو په هغه وخت کې خوښي وکړئ او د خوشحالۍ ټوپونه ووهئ، ځکه چې په جنت کې به لوی اجر ولرئ. د هغوی نیکونو هم د پیغمبرانو سره همداسې چلند کړی ؤ.', 'نو په هغه وخت کې خوشی وکری او د خوشحالی توپونه ووهی، جکه چې په جنت کې به لوی اجر ولری. د هغوی نیکونو هم د پیغمبرانو سره همداسې چلند کری و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(27587, 'Luke 6:24', 'Luke', 6, 24, 'خو افسوس دې وي ستاسو شتمنو په حال! ځکه چې تاسو خپل د سوکالۍ وخت تېر کړی دی.', 'خو افسوس دې وی ستاسو شتمنو په حال! جکه چې تاسو خپل د سوکالی وخت تېر کری دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27588, 'Luke 6:25', 'Luke', 6, 25, 'افسوس دې وي ستاسو په حال چې اوس ماړه یئ، ځکه چې تاسو به وږي شئ افسوس دې وي په تاسو چې اوس خاندئ، ځکه چې ستاسو خندا به په ویر او ژړا بدله شي', 'افسوس دې وی ستاسو په حال چې اوس ماره یی، جکه چې تاسو به وزی شی افسوس دې وی په تاسو چې اوس خاندی، جکه چې ستاسو خندا به په ویر او ژرا بدله شی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_6_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
